  (1, 1, 3, '{"prompt":"Which sentence is right?","choices":["After school, they wait for Jun and then hurried home.","After school, they waited for Jun and then hurryed home.","After school, they waited for Jun and then hurried home."],"answer":2,"picture":"school"}'),
