-- ============================ PART 2: APPLY ================================
-- Only run this after you checked the rows from PART 1.
-- It runs as one all-or-nothing step: either every change happens, or none.

begin;

-- Test week · Grade 3
do $$ begin if not exists (select 1 from wp_classes where grade = 3) then
  raise exception 'No class for grade 3: import the roster first'; end if; end $$;
insert into wp_plans (title, kind) values ('Test week · Grade 3', 'test') on conflict (title) do update set kind = excluded.kind;
insert into wp_plan_assignments (plan_id, class_id)
  select (select id from wp_plans where title = 'Test week · Grade 3'), (select id from wp_classes where grade = 3 order by name, id limit 1) where not exists (select 1 from wp_plan_assignments where plan_id = (select id from wp_plans where title = 'Test week · Grade 3') and class_id = (select id from wp_classes where grade = 3 order by name, id limit 1));
insert into wp_weeks (plan_id, position, skill, opens_on) values ((select id from wp_plans where title = 'Test week · Grade 3'), 1, 'Past tense in stories', '2026-11-26')
  on conflict (plan_id, position) do nothing;
insert into wp_lessons (week_id, position, title) values ((select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 3') and position = 1), 1, 'Add -ed the right way')
  on conflict (week_id, position) do nothing;
update wp_questions set type = 'pick_one', payload = '{"prompt":"Which one would your teacher write?","choices":["Last night the baby cryed, so Mom picked her up.","Last night the baby cried, so Mom picked her up.","Last night the baby cried, so Mom pick her up."],"answer":1,"picture":"baby"}'::jsonb, skill = 'past-tense', updated_at = now()
  where lesson_id = (select id from wp_lessons where week_id = (select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 3') and position = 1) and position = 1) and position = 1 and deleted_at is null
  and (type <> 'pick_one' or payload <> '{"prompt":"Which one would your teacher write?","choices":["Last night the baby cryed, so Mom picked her up.","Last night the baby cried, so Mom picked her up.","Last night the baby cried, so Mom pick her up."],"answer":1,"picture":"baby"}'::jsonb or skill is distinct from 'past-tense');
insert into wp_questions (lesson_id, position, type, payload, skill) select (select id from wp_lessons where week_id = (select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 3') and position = 1) and position = 1), 1, 'pick_one', '{"prompt":"Which one would your teacher write?","choices":["Last night the baby cryed, so Mom picked her up.","Last night the baby cried, so Mom picked her up.","Last night the baby cried, so Mom pick her up."],"answer":1,"picture":"baby"}'::jsonb, 'past-tense'
