  where not exists (select 1 from wp_questions where lesson_id = (select id from wp_lessons where week_id = (select id from wp_weeks where plan_id = (select id from wp_plans where title = 'Test week · Grade 3') and position = 1) and position = 5) and position = 15);

commit;
